<template><section class="warehouse-page" v-loading="loading"><div class="toolbar"><el-button v-if="(kind==='inventory'?allows('metal:warehouse-order:add'):can('add'))&&kind!=='warning-record'&&kind!=='work-report'" class="blue" @click="add">添加</el-button><el-button v-if="['warehouse','warning-rule','inventory'].includes(kind)&&(kind==='inventory'?can('adjust'):can('edit'))" class="orange" :disabled="selected.length!==1" @click="edit(selected[0])">{{kind==='inventory'?'库存调整':'编辑'}}</el-button><el-button v-if="['warehouse','inventory','warning-rule','warning-record'].includes(kind)&&can('remove')" class="red" :disabled="!selected.length" @click="remove(selected)">删除</el-button><template v-if="kind==='warehouse-order'"><el-button class="orange" disabled title="已过账不能直接编辑，请查看后冲销">编辑</el-button><el-button class="red" disabled title="已过账不能直接删除，请查看后冲销">删除</el-button></template><BusinessFilters v-if="kind==='warehouse-order'" kind="warehouse-order" :order-kind="tab" :allow-export="can('export')" :exporting="exporting" @apply="applyFilters" @export="exportRows"/></div>
 <el-tabs type="card" v-if="tabs.length" v-model="tab" @tab-change="query.pageNum=1;load()"><el-tab-pane v-for="t in tabs" :key="t.value" :name="t.value" :label="t.label"/></el-tabs>
