 <div v-if="failed" class="error"><el-button link @click="load">加载失败，点击重试</el-button></div><div class="pagination"><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" :page-sizes="[16,32,64]" layout="total, sizes, prev, pager, next, jumper" @current-change="load" @size-change="query.pageNum=1;load()"/></div>
 <WarehouseOrderForm ref="orderForm" @saved="load"/><BatchForm ref="batchForm" @saved="load"/>
