 <el-dialog v-model="detailVisible" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving" :title="kind==='work-report'?'查看报工':title+'详情'" width="min(900px,94vw)" class="warehouse-dialog"><template v-if="detail"><div class="detail-info"><div v-for="c in detailFields" :key="c.key"><span class="detail-label">{{c.title}}：</span><span class="detail-value">{{display(detail,c.key)}}</span></div></div><p v-if="kind==='inventory'">实测净重：{{detail.netWeight}} g；数量：{{detail.quantity}} 件</p><p v-if="kind==='work-report'">按领用净重比例分摊；{{detail.voided?'报工已作废':stateNames[detail.status]}}</p><template v-if="detail.lines"><template v-if="rawDetailLines.length"><h4 class="stock-detail-title">原材料明细</h4><el-table :data="rawDetailLines" border class="raw-order-detail"><el-table-column label="物料编码" prop="code"/><el-table-column label="单位名称" prop="organization"/><el-table-column label="品名/类别" prop="name"/><el-table-column label="规格型号" prop="specification"/><el-table-column label="毛重(g)" prop="grossWeight"/><el-table-column label="杂质(g)" prop="impurity"/><el-table-column label="净重(g)" prop="netWeight"/><el-table-column label="用途" prop="purpose"/><el-table-column label="备注" prop="remark"/></el-table></template><template v-for="group in productDetailGroups" :key="group.category"><template v-if="group.lines.length"><h4 class="stock-detail-title">{{group.title}}</h4><el-table :data="group.lines" border :class="group.category==='FINISHED'?'finished-order-detail':'semi-order-detail'"><el-table-column label="物料编码" prop="code"/><el-table-column label="单位名称" prop="organization"/><el-table-column label="收货单位" prop="receivingOrganization"/><el-table-column label="批次号" prop="batchNo"/><el-table-column label="品名/类别" prop="name"/><el-table-column label="规格型号" prop="specification"/><el-table-column label="纯度(%)" prop="purity"/><el-table-column label="数量(件)" prop="quantity"/><el-table-column label="实测净重(g)" prop="netWeight"/><el-table-column label="备注" prop="remark"/></el-table></template></template></template><el-table v-if="detail.materials" :data="detail.materials" border><el-table-column label="物料编码" prop="code"/><el-table-column label="物料名称" prop="name"/><el-table-column label="损耗重量(g)" prop="lossWeight"/><el-table-column label="平均损耗(g)" prop="averageLoss"/></el-table><el-table v-if="detail.ledger" :data="detail.ledger" border><el-table-column label="来源单据" prop="orderNo"/><el-table-column label="净重变化(g)" prop="deltaWeight"/><el-table-column label="数量变化" prop="deltaQuantity"/><el-table-column label="净重余额(g)" prop="balanceWeight"/><el-table-column label="数量余额" prop="balanceQuantity"/></el-table><el-table v-if="detail.orders" :data="detail.orders" border><el-table-column label="单据编号" prop="orderNo"/><el-table-column label="类型"><template #default="{row}">{{orderTypeNames[row.type]}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{stateNames[row.status]}}</template></el-table-column></el-table><template v-if="kind==='warning-record'"><p>实际平均损耗：{{detail.averageLoss}} g；超差量：{{excess}} g</p><p v-if="detail.sourceVoid">来源报工已作废</p><p v-if="detail.result">处理结果：{{detail.result}}；处理人：{{detail.handlerName}}；时间：{{detail.handledTime}}</p><el-table v-if="detail.report?.materials" :data="detail.report.materials" border><el-table-column label="物料编码" prop="code"/><el-table-column label="物料名称" prop="name"/><el-table-column label="损耗重量(g)" prop="lossWeight"/><el-table-column label="平均损耗(g)" prop="averageLoss"/></el-table><el-table v-if="detail.history" :data="detail.history" border><el-table-column label="操作" prop="action"/><el-table-column label="结果" prop="result"/><el-table-column label="操作人" prop="actorName"/><el-table-column label="时间" prop="createTime"/></el-table><el-input v-if="can('handle')&&detail.status==='PENDING'&&!detail.sourceVoid" v-model="reason" type="textarea" maxlength="500" placeholder="填写处理结果"/></template><template v-if="kind==='warehouse-order'&&detail.batchStatus==='OPEN'&&allows('metal:process-batch:settle')"><p>加工批次号：{{detail.batchNo}}</p><el-form-item label="实际完成数量"><el-input v-model.number="completedQuantity" inputmode="numeric"/></el-form-item><p>全部领还料和产出登记完毕后结算；完成数量须等于该批次已入库产出数量。</p></template><template v-if="kind==='process-batch'&&detail.status==='OPEN'&&can('settle')"><el-form-item label="实际完成数量"><el-input v-model.number="completedQuantity" inputmode="numeric"/></el-form-item><p>结算前须登记全部领回料及产出，产出数量须等于完成数量。</p></template></template><template #footer><el-button @click="detailVisible=false">关闭</el-button><el-button v-if="kind==='inventory'&&can('adjust')" type="warning" @click="openAdjustment">调整库存</el-button><el-button v-if="['warehouse-order','process-batch'].includes(kind)&&can('reverse')&&(!detail?.batchId||allows('metal:process-batch:reverse'))&&detail?.status!=='VOID'" type="danger" :loading="saving" @click="reverse">冲销</el-button><el-button v-if="kind==='warehouse-order'&&detail?.batchStatus==='OPEN'&&allows('metal:process-batch:settle')" type="primary" :loading="saving" @click="settleBoundBatch">结算</el-button><el-button v-if="kind==='process-batch'&&detail?.status==='OPEN'&&can('settle')" type="primary" :loading="saving" @click="settle">结算</el-button><el-button v-if="kind==='warning-record'&&can('handle')&&detail?.status==='PENDING'&&!detail.sourceVoid" type="primary" :loading="saving" @click="handle">确认处理</el-button></template></el-dialog>
 <el-dialog v-model="adjustVisible" title="库存调整" width="min(560px,94vw)" :close-on-click-modal="false"><el-form label-width="140px"><el-form-item label="净重差额(g)"><el-input v-model="adjust.deltaWeight" inputmode="decimal" placeholder="增加填正数，减少填负数"/></el-form-item><el-form-item v-if="detail?.category!=='RAW'" label="数量差额"><el-input v-model.number="adjust.deltaQuantity" inputmode="numeric"/></el-form-item><el-form-item label="经手人"><el-select v-model="adjust.operatorId" fit-input-width><el-option v-for="o in adjustPeople" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="仓管员"><el-select v-model="adjust.keeperId" fit-input-width><el-option v-for="o in adjustPeople" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="调整原因"><el-input v-model="adjust.reason" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="adjustVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAdjustment">确认</el-button></template></el-dialog>
</section></template>
<script setup lang="ts">
import BusinessFilters from '@/components/BusinessFilters/index.vue'
import {download} from '@/utils/request'
import {createUUID} from '@/utils/uuid'
import{ref,reactive,computed,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import useUserStore from '@/store/modules/user';import{warehouseList,warehouseDetail,warehouseSave,warehouseRemove,warehouseAction,warehouseOptions,stateNames,orderTypeNames,type Row}from'@/api/metal/warehouse';import WarehouseOrderForm from './WarehouseOrderForm.vue';import BatchForm from './BatchForm.vue';
const props=defineProps<{kind:string}>(),kind=props.kind,user=useUserStore(),admin=computed(()=>String(user.id)==='1'),can=(action:string)=>user.permissions.includes('*:*:*')||user.permissions.includes('metal:'+kind+':'+action),title=({'warehouse':'仓库字典','inventory':'库存管理','warehouse-order':'仓储工单管理','process-batch':'加工批次','work-report':'报工','warning-rule':'预警规则','warning-record':'预警记录'}as Record<string,string>)[kind];
const showActions=computed(()=>can('query')||(kind==='inventory'&&can('adjust'))||(['warehouse','warning-rule','warehouse-order'].includes(kind)&&can('edit'))||can('remove'));
const inventoryMode=ref('info');
const loading=ref(false),saving=ref(false),failed=ref(false),rows=ref<Row[]>([]),total=ref(0),selected=ref<Row[]>([]),query=reactive({pageNum:1,pageSize:16}),tab=ref(kind==='inventory'?'RAW':'OUT'),orderForm=ref<InstanceType<typeof WarehouseOrderForm>>(),batchForm=ref<InstanceType<typeof BatchForm>>(),formVisible=ref(false),detailVisible=ref(false),detail=ref<Row>(),form=reactive<Row>({}),factories=ref<Row[]>([]),products=ref<Row[]>([]),processes=ref<Row[]>([]),reason=ref(''),completedQuantity=ref(1),adjustVisible=ref(false),adjust=reactive<Row>({}),adjustPeople=ref<Row[]>([]);
const tabs=kind==='inventory'?[{label:'原材料',value:'RAW'},{label:'成品',value:'FINISHED'},{label:'半成品',value:'SEMI'}]:kind==='warehouse-order'?[{label:'出库单',value:'OUT'},{label:'入库单',value:'IN'},{label:'还库单',value:'RET'}]:[];
const c=(title:string,key:string,width?:number)=>({title,key,width});
const columns=computed(()=>kind==='warehouse'?[c('序号','sortOrder'),c('字典项名称','name'),c('工厂名称','factoryName'),c('状态','status'),c('创建时间','createTime',140)]:kind==='inventory'?(tab.value==='RAW'?[c('物料编码','code',98),c('品名','name',98),c('单位名称','organization',160),c('规格型号','specification',120),c('仓库/库房','warehouseName',104),c('净重（单位g）','netWeight',184),c('更新时间','updateTime',180)]:[c('物料编码','code'),c('批次号','batchNo',140),c('品名','name'),c('规格型号','specification'),c('仓库/库房','warehouseName'),c('纯度','purity'),c('单位名称','organization'),c('数量','quantity'),c('更新时间','updateTime',140)]):kind==='warehouse-order'?[c('单据编号','orderNo',98),...(tab.value!=='IN'?[c(tab.value==='RET'?'出库工单':'生产工单','sourceOrderNo',120)]:[]),c(tab.value==='OUT'?'出库时间':tab.value==='RET'?'还库时间':'入库时间','orderDate',125),c('仓库/库房','warehouseName',136),c(tab.value==='OUT'?'出库类型':tab.value==='RET'?'还库类型':'入库类型','type',115),c('经办人','operatorName',93),c(tab.value==='OUT'?'领用人':'验收人',tab.value==='OUT'?'recipientName':'inspectorName',98),c('仓管员','keeperName',88),c('审核人','reviewerName',90)]:kind==='warning-rule'?[c('所属工厂','factoryName'),c('产品','productName'),c('工序','processName'),c('允许超差(g)','tolerance'),c('状态','status'),c('创建时间','createTime',140)]:kind==='warning-record'?[c('工序名称','processName'),c('预警值','thresholdValue'),c('理论损耗','theoreticalLoss'),c('产品类型','productCategory'),c('规格型号','specification'),c('生产单号','orderNo',150),c('状态','status'),c('触发时间','triggerTime',140)]:kind==='process-batch'?[c('批次','id'),c('生产单号','orderNo',150),c('工序名称','processName'),c('加工数量','plannedQuantity'),c('完成数量','completedQuantity'),c('状态','status'),c('创建时间','createTime',140)]:[c('批次','batchId'),c('生产单号','orderNo',150),c('工序名称','processName'),c('领料净重(g)','issuedWeight'),c('回料净重(g)','returnedWeight'),c('损耗重量(g)','lossWeight'),c('平均损耗(g)','averageLoss'),c('状态','status')]);
const rawDetailLines=computed(()=>((detail.value?.lines??[]) as Row[]).filter(line=>line.category==='RAW'));const productDetailGroups=computed(()=>[{category:'FINISHED',title:'成品明细'},{category:'SEMI',title:'半成品明细'}].map(group=>({...group,lines:((detail.value?.lines??[]) as Row[]).filter(line=>line.category===group.category)})));
const detailFields=computed(()=>columns.value.filter(f=>f.key!=='status').concat(kind==='inventory'?[]:[c('状态','status')])),excess=computed(()=>detail.value?(Number(detail.value.averageLoss)-Number(detail.value.thresholdValue)).toFixed(6):'0');
function display(row:Row,key:string){if(key==='organization')return String(row[key]??'').trim()||'—';if(key.endsWith('Time')&&typeof row[key]==='string')return row[key].replace('T',' ').slice(0,19);if(key==='status')return row.sourceVoid?'来源作废':stateNames[row[key]]||(row[key]==='0'?'启用':row[key]==='1'?'停用':row[key]||'—');if(key==='type')return orderTypeNames[row[key]]||row[key];if(key==='sourceOrderNo'&&tab.value==='OUT')return row.workOrderNo||'—';return row[key]??'—'}
const appliedFilters=ref<Record<string,string>>({}),exporting=ref(false),listTable=ref<{clearSelection:()=>void}>()
function applyFilters(filters:Record<string,string>){appliedFilters.value=filters;query.pageNum=1;selected.value=[];listTable.value?.clearSelection();load()}
async function exportRows(filters:Record<string,string>){if(exporting.value)return;exporting.value=true;try{await download('/metal/warehouse-order/export',{...filters,filter:tab.value},'仓储工单.xlsx',{timeout:0})}finally{exporting.value=false}}
let loadEpoch=0
async function load(){const current=++loadEpoch;loading.value=true;failed.value=false;selected.value=[];try{const r=await warehouseList(kind,{...query,...appliedFilters.value,filter:tabs.length?tab.value:undefined});if(current!==loadEpoch)return;rows.value=r.rows;total.value=r.total;selected.value=[]}catch{if(current===loadEpoch)failed.value=true}finally{if(current===loadEpoch)loading.value=false}}
async function add(){if(kind==='inventory'){await orderForm.value?.open('IN',false,tab.value);return}if(kind==='warehouse-order'){await orderForm.value?.open(tab.value);return}if(kind==='process-batch'){await batchForm.value?.open();return}Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{requestId:createUUID(),factoryId:'',name:'',sortOrder:0,status:'0',tolerance:'0'});factories.value=(await warehouseOptions('factories')).data;if(!admin.value)form.factoryId=factories.value[0]?.id;if(form.factoryId)await factoryChanged();formVisible.value=true}
function isReferenced(row?:Row){return !!row&&[true,1,'1'].includes(row.businessReferenced)}
async function edit(row:Row){if(kind==='inventory'){detail.value=(await warehouseDetail(kind,row.id)).data;await openAdjustment();return}const r=(await warehouseDetail(kind,row.id)).data;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,r);factories.value=(await warehouseOptions('factories')).data;if(kind==='inventory'){detail.value=r;inventoryMode.value=can('adjust')&&(!can('edit')||isReferenced(r))?'adjust':'info';adjustPeople.value=(await warehouseOptions('people',r.factoryId)).data;Object.assign(adjust,{requestId:createUUID(),version:r.version,operatorId:'',keeperId:'',deltaWeight:'0',deltaQuantity:0,reason:''})}if(kind==='warning-rule'){products.value=(await warehouseOptions('products',form.factoryId)).data;processes.value=(await warehouseOptions('processes',form.factoryId,form.productId)).data}formVisible.value=true}
async function factoryChanged(){if(kind==='warning-rule'){form.productId='';form.processId='';products.value=(await warehouseOptions('products',form.factoryId)).data;processes.value=[]}}
async function productChanged(){form.processId='';processes.value=(await warehouseOptions('processes',form.factoryId,form.productId)).data}
async function save(){if(kind==='warehouse'&&(!form.factoryId||!form.name?.trim()||!Number.isInteger(form.sortOrder)||form.sortOrder<0)){ElMessage.error('请填写库房名称及非负整数顺序');return}if(kind==='warning-rule'&&(!form.factoryId||!form.productId||!form.processId||!/^\d+(\.\d{1,6})?$/.test(String(form.tolerance)))){ElMessage.error('请选择产品工序并填写非负克数超差');return}saving.value=true;try{await warehouseSave(kind,{...form,purity:form.purity||null});formVisible.value=false;ElMessage.success('保存成功');await load()}finally{saving.value=false}}
async function toggle(row:Row,value:any){saving.value=true;try{await warehouseSave(kind,{...row,status:value});await load()}finally{saving.value=false}}
async function remove(targets:Row[]){try{await ElMessageBox.confirm('确认归档选中的'+targets.length+'条记录？','删除确认')}catch{return}saving.value=true;try{await warehouseRemove(kind,targets.map(r=>r.id));ElMessage.success('归档成功');await load()}finally{saving.value=false}}
let detailEpoch=0
async function view(row:Row){if(saving.value)return;const current=++detailEpoch;detail.value=undefined;detailVisible.value=false;const response=await warehouseDetail(kind,row.id);if(current!==detailEpoch)return;detail.value=response.data;reason.value='';completedQuantity.value=detail.value.plannedQuantity||1;detailVisible.value=true}
async function reverse(){if(saving.value||!detail.value)return;const target={...detail.value};saving.value=true;try{let value;try{value=await ElMessageBox.prompt(target.batchId?'填写冲销原因，将整体撤回该批次的所有领料、还料和产出单据':'填写冲销原因','冲销确认',{inputValidator:v=>!!v?.trim()||'原因必填',inputPattern:/^[\s\S]{1,500}$/,inputErrorMessage:'最多500字符'})}catch{return}await warehouseAction(target.batchId?'process-batch':kind,target.batchId||target.id,'reverse',{version:target.batchId?target.batchVersion:target.version,reason:value.value});detailVisible.value=false;await load();ElMessage.success('冲销成功')}finally{saving.value=false}}
function allows(permission:string){return user.permissions.includes('*:*:*')||user.permissions.includes(permission)}
async function settleBoundBatch(){if(saving.value)return;if(!detail.value||!Number.isInteger(completedQuantity.value)||completedQuantity.value<1){ElMessage.error('请填写正整数完成数量');return}saving.value=true;try{await warehouseAction('process-batch',detail.value.batchId,'settle',{version:detail.value.batchVersion,completedQuantity:completedQuantity.value});detailVisible.value=false;await load();ElMessage.success('已结算并生成报工')}finally{saving.value=false}}
async function settle(){if(saving.value)return;if(!detail.value)return;saving.value=true;try{await warehouseAction(kind,detail.value.id,'settle',{version:detail.value.version,completedQuantity:completedQuantity.value});detailVisible.value=false;await load();ElMessage.success('结算成功')}finally{saving.value=false}}
async function handle(){if(saving.value||!detail.value)return;if(!reason.value.trim()){ElMessage.error('请填写处理结果');return}saving.value=true;try{await warehouseAction(kind,detail.value!.id,'handle',{version:detail.value!.version,reason:reason.value});detailVisible.value=false;await load();ElMessage.success('处理成功')}finally{saving.value=false}}
async function openAdjustment(){adjustPeople.value=(await warehouseOptions('people',detail.value!.factoryId)).data;Object.assign(adjust,{requestId:createUUID(),version:detail.value!.version,operatorId:'',keeperId:'',deltaWeight:'0',deltaQuantity:0,reason:''});adjustVisible.value=true}
async function saveAdjustment(){if(!adjust.operatorId||!adjust.keeperId||!adjust.reason?.trim()||!Number.isInteger(adjust.deltaQuantity)||!/^[-+]?\d+(\.\d{1,6})?$/.test(String(adjust.deltaWeight))){ElMessage.error('请填写合法调整差额及原因');return}saving.value=true;try{await warehouseAction('inventory',detail.value!.id,'adjust',adjust);adjustVisible.value=false;detailVisible.value=false;formVisible.value=false;await load();ElMessage.success('调整已登记')}finally{saving.value=false}}
onMounted(load)
</script>
