.warehouse-order-table :deep(th.el-table__cell){height:69px}.warehouse-order-table :deep(td.el-table__cell){height:44px;padding:0}.warehouse-order-table :deep(td .cell){padding:0 5px}.warehouse-order-table :deep(.el-table__body td:last-child .cell){display:flex;align-items:center;justify-content:center;gap:4px;white-space:nowrap;flex-wrap:nowrap}.warehouse-order-table .small{margin:0;flex-shrink:0}.warehouse-order-table :deep(.el-button:disabled){opacity:.6}
.stock-detail-title{font-size:14px;font-weight:600;margin:20px 0 10px}
.detail-info>div{display:flex;align-items:flex-start;text-align:left;min-width:0}.detail-label{white-space:nowrap;flex-shrink:0;text-align:left}.detail-value{min-width:0;overflow-wrap:anywhere;text-align:left}

